@namespace sv_f7a0adc4ff4d4e3bac036490abfd017b.Components.Pages.Settings
@using sv_f7a0adc4ff4d4e3bac036490abfd017b.Services
@inject ISettingsService SettingsService

<div class="card mb-3">
    <div class="card-header"><h5 class="mb-0">Security Settings</h5></div>
    <div class="card-body">
        @if (_loading)
        {
            <p>Loading...</p>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert @(_isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }

            <!-- Change Password Panel -->
            <div class="mb-4">
                <button class="btn btn-outline-secondary mb-2" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    @(_passwordPanelOpen ? "▼" : "▶") Change Password
                </button>

                @if (_passwordPanelOpen)
                {
                    <div class="card card-body bg-light">
                        <div class="mb-2">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-2">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="ChangePasswordAsync">Update Password</button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="mb-4">
                <h6>Two-Factor Authentication</h6>
                <div class="d-flex align-items-center gap-3">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="twoFactor" checked="@_twoFactorEnabled" disabled />
                        <label class="form-check-label" for="twoFactor">Two-Factor Authentication</label>
                    </div>
                    <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-warning")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                @if (_lastPasswordChange.HasValue)
                {
                    <small class="text-muted">Last password change: @_lastPasswordChange.Value.ToString("f")</small>
                }
            </div>

            <!-- Active Sessions -->
            <div class="mb-3">
                <h6>Active Sessions</h6>
                <div class="table-responsive">
                    <table class="table table-sm table-hover">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _sessions)
                            {
                                <ActiveSessionRow Session="session"
                                                  IsCurrentSession="session == _sessions.FirstOrDefault()"
                                                  OnRevokeRequested="ShowRevokeConfirmation" />
                            }
                        </tbody>
                    </table>
                </div>
            </div>

            <!-- Revoke Confirmation Dialog -->
            @if (_sessionToRevoke is not null)
            {
                <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
                    <div class="modal-dialog">
                        <div class="modal-content">
                            <div class="modal-header">
                                <h5 class="modal-title">Confirm Session Revocation</h5>
                                <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                            </div>
                            <div class="modal-body">
                                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                            </div>
                            <div class="modal-footer">
                                <button type="button" class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                <button type="button" class="btn btn-danger" @onclick="ConfirmRevokeAsync">Revoke Session</button>
                            </div>
                        </div>
                    </div>
                </div>
            }
        }
    </div>
</div>

@code {
    private bool _loading = true;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();
    private ActiveSession? _sessionToRevoke;
    private string? _message;
    private bool _isError;

    protected override async Task OnInitializedAsync()
    {
        await LoadSettingsAsync();
        _loading = false;
    }

    private async Task LoadSettingsAsync()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions;
    }

    private async Task ChangePasswordAsync()
    {
        if (_newPassword != _confirmPassword)
        {
            _message = "New password and confirmation do not match.";
            _isError = true;
            return;
        }

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _message = "New password cannot be empty.";
            _isError = true;
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _message = "Password updated successfully!";
        _isError = false;
        _passwordPanelOpen = false;
    }

    private void ShowRevokeConfirmation(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessions.Remove(_sessionToRevoke);
            _sessionToRevoke = null;
            _message = "Session revoked successfully.";
            _isError = false;
        }
    }
}

